constexpr size_t MAP_SIZE = sizeof(CODEPOINT_MAP) / sizeof(CODEPOINT_MAP[0]);

inline int getGlyphIndex(uint32_t codepoint) {
    if (codepoint >= 32 && codepoint <= 126) {
        return static_cast<int>(codepoint - 32);
    }
    for (size_t i = 95; i < MAP_SIZE; ++i) {
        if (CODEPOINT_MAP[i].codepoint == codepoint) {
            return static_cast<int>(CODEPOINT_MAP[i].glyphIndex);
        }
    }
    return static_cast<int>('?' - 32); // Fallback to '?'
}

